    const moveBlock = panBlock.match(/const onPointerMove = \(moveEvent\) => \{[\s\S]*?\n  \};/)?.[0] ?? "";
    const upBlock = panBlock.match(/const onPointerUp = \(\) => \{[\s\S]*?\n  \};/)?.[0] ?? "";

    assert.match(moveBlock, /--canvas-pan-x/);
