  it("deletes only the selected storyboard conversation turn from history and backend", async () => {
    const calls = [];
    const storyboards = addStoryboard([]).map((storyboard) => ({
      ...storyboard,
      id: "storyboard-10000000-0000-4000-8000-000000000777",
    }));
    const deletedEntry = {
      storyboardId: storyboards[0].id,
      mediaKind: "video",
      taskId: "storyboard-video-task-delete",
      promptPreview: "删除这一条。",
    };
    const remainingEntry = {
      storyboardId: storyboards[0].id,
      mediaKind: "video",
      taskId: "storyboard-video-task-keep",
      promptPreview: "保留这一条。",
    };
    storyboards[0] = {
      ...storyboards[0],
      generationState: {
        ...(storyboards[0].generationState ?? {}),
        lastSubmission: deletedEntry,
      },
    };
    const workbench = {
      ui: buildProjectUi({
        projectPanelMode: "episode-workbench",
        selectedEpisodeId: "10000000-0000-4000-8000-000000000001",
        museScopeMode: "storyboard",
        episodeMediaMode: "video",
        selectedStoryboardId: storyboards[0].id,
        storyboards,
        storyboardConversationHistory: {
          [`video:${storyboards[0].id}`]: [deletedEntry, remainingEntry],
        },
        videoGenerationResult: deletedEntry,
      }),
      state: {
        ...buildProjectState(),
        projectDetail: {
          project: { id: "project-1", projectId: "project-1", name: "try" },
          episodes: [
            {
              id: "10000000-0000-4000-8000-000000000001",
              title: "真实剧集",
              status: "draft",
              storyboardCount: 1,
            },
          ],
          shots: [],
        },
      },
      api: {
        async deleteStoryboardConversationTurn(episodeId, storyboardId, taskId, mediaMode) {
          calls.push({ episodeId, storyboardId, taskId, mediaMode });
          return { deleted: true, entries: [remainingEntry] };
        },
      },
      root: {
        innerHTML: "",
        querySelector(selector) {
          if (selector !== ".episode-replica-stage-body") {
            return null;
          }
          return {
            innerHTML: "",
          };
        },
      },
    };

    await handleWorkbenchActionForTest(workbench, {
      dataset: {
        action: "episode-result-action",
        resultAction: "delete",
        mediaKind: "video",
        taskId: "storyboard-video-task-delete",
      },
    });

    assert.deepEqual(calls, []);
    assert.deepEqual(workbench.ui.generationResultDeleteTarget, {
      scope: "storyboard",
      mediaKind: "video",
      storyboardId: "storyboard-10000000-0000-4000-8000-000000000777",
      taskId: "storyboard-video-task-delete",
    });

    await handleWorkbenchActionForTest(workbench, {
      dataset: {
        action: "confirm-delete-generation-result",
      },
    });

    assert.deepEqual(calls, [
      {
        episodeId: "10000000-0000-4000-8000-000000000001",
        storyboardId: "10000000-0000-4000-8000-000000000777",
        taskId: "storyboard-video-task-delete",
        mediaMode: "video",
      },
    ]);
    assert.equal(workbench.ui.storyboardConversationHistory[`video:${storyboards[0].id}`].length, 1);
    assert.equal(
      workbench.ui.storyboardConversationHistory[`video:${storyboards[0].id}`][0]?.taskId,
      remainingEntry.taskId,
    );
    assert.equal(workbench.ui.videoGenerationResult?.taskId, "storyboard-video-task-keep");
    assert.equal(workbench.ui.selectedStoryboard?.generationState?.lastSubmission ?? null, null);

    await applyTaskCenterTaskProjectionForTest(workbench, {
      ...deletedEntry,
      status: "failed",
      workflowStatus: "failed",
      targetType: "storyboard",
      targetId: storyboards[0].id,
      failure: { displayMessage: "删除后的旧任务回调不得恢复结果。" },
    });
    assert.equal(workbench.ui.storyboardConversationHistory[`video:${storyboards[0].id}`].length, 1);
    assert.equal(workbench.ui.videoGenerationResult?.taskId, "storyboard-video-task-keep");

    workbench.api.deleteStoryboardConversationTurn = async () => ({
      deleted: false,
      deletedCount: 0,
      entries: [remainingEntry],
    });
    workbench.ui.generationResultDeleteTarget = {
      scope: "storyboard",
      mediaKind: "video",
      storyboardId: storyboards[0].id,
      taskId: remainingEntry.taskId,
    };
    await handleWorkbenchActionForTest(workbench, {
      dataset: { action: "confirm-delete-generation-result" },
    });
    assert.equal(workbench.ui.storyboardConversationHistory[`video:${storyboards[0].id}`].length, 1);
    assert.match(workbench.ui.toast, /删除失败/);
  });

